import random

class Device:
    def __init__(self, id):
        self.id = id
        self.infected = False

def initialize_network(num_devices, infection_probability):
    network = {}
    for i in range(num_devices):
        network[i] = Device(i)

    # Randomly connect devices
    for i in range(num_devices):
        num_connections = random.randint(1, num_devices // 2)
        for _ in range(num_connections):
            neighbor_id = random.randint(0, num_devices - 1)
            if not network[neighbor_id].infected:
                network[i].infected = True
                network[neighbor_id].infected = True

    return network

def simulate_infection(network, infection_probability, rounds):
    for _ in range(rounds):
        new_infected = []

        # Check each device
        for device in network.values():
            if not device.infected:
                if infection_probability > random.random():
                    device.infected = True
                    new_infected.append(device)

        # Infect connected devices
        for uninfected_device in new_infected:
            for uninfected_neighbor in network.keys():
                if not network[uninfected_neighbor].infected:
                    if uninfected_neighbor != uninfected_device.id:
                        network[uninfected_neighbor].infected = True

    return [device.id for uninfected_device in network.values() if not uninfected_device.infected]

